---@class UIOutDoorMainBtnNode
---@field area                          	UnityEngine.RectTransform               
---@field ImgLock                       	UnityEngine.RectTransform               
---@field Text                          	UnityEngine.RectTransform                                       
local UIOutDoorMainBtnNode = Class("UIOutDoorMainBtnNode")
function UIOutDoorMainBtnNode:__init() 
    self._data = nil
    self.isOpened = true
    self.unOpenedToast = ""

end

function UIOutDoorMainBtnNode:__delete()
    self._data = nil
    self.isOpened = nil
    self.unOpenedToast = nil

end

function UIOutDoorMainBtnNode:Awake()
    SetButtonAction(self.controller, Bind(self, self.OnClick))
end

function UIOutDoorMainBtnNode:Start()

end

function UIOutDoorMainBtnNode:Refresh(data, ind)
    if not data then
        return
    end
    self._data = data

    self:FillSelf()

    self._co = CfUtils.PlayDelayShowAnimate(self.controller.gameObject.transform:Find("AnimRoot"), ind)
end

function UIOutDoorMainBtnNode:FillSelf()
    GameUtils.RefeshSystemToggleId(self.controller, self._data.systemToggleId)
    CfUtils.FillImage(self.ImgSymbol, string.format("UIAtlas/Outdoor/outdoor_img_%d.png", self._data.systemToggleId))
    self.isOpened = true
    if self._data.isOpened and type(self._data.isOpened) == "function" then
        self.isOpened, self.unOpenedToast = self._data.isOpened()
    end
    local isUnlock = (GameUtils.IsUnlockedBySystemTogId(self._data.systemToggleId) and self._data.systemToggleId ~= Constants.SystemToggleIds.None)
    KTool.SetActive(self.ImgLock, (not isUnlock) or (not self.isOpened))
    --KTool.SetActive(self.Text, isUnlock)
    CfUtils.FillText(self.Text, self._data.name)
    if isUnlock and self.isOpened then
        self.BtnBg.alpha = 1
    else
        self.BtnBg.alpha = 0.7
    end
    self:RefeshRedPoint(self._data)
end

function UIOutDoorMainBtnNode:RefeshRedPoint(data)
    if data.systemToggleId == Constants.SystemToggleIds.Id207 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneAchievement, self.controller.gameObject.transform:Find("AnimRoot"), true)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id222 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneReward, self.controller.gameObject.transform:Find("AnimRoot"), true)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id221 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneMessage, self.controller.gameObject.transform:Find("AnimRoot"), true)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id210 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneInvestigate, self.controller.gameObject.transform:Find("AnimRoot"), true, Vector2(0, 41))
    elseif data.systemToggleId == Constants.SystemToggleIds.Id232 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneWeekTask, self.controller.gameObject.transform:Find("AnimRoot"), true)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id233 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneFish, self.controller.gameObject.transform:Find("AnimRoot"), true)
    end
end

function UIOutDoorMainBtnNode:RemoveRedPoint()
    if not self._data then
        return
    end
    local data = self._data
    if data.systemToggleId == Constants.SystemToggleIds.Id207 then
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneAchievement)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id222 then
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneReward)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id221 then
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneMessage)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id210 then
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneInvestigate)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id232 then
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneWeekTask)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id233 then
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneFish)
    end
end

function UIOutDoorMainBtnNode:OnClick()
    if not self._data then
        return
    end
    if checkNumber(self._data.systemToggleId) == 0 then 
        GameUtils.Toast(localize("暂未开放"))
        return
    end
    if GameUtils.IsUnlockedBySystemTogId(self._data.systemToggleId) then
        if self.isOpened then--解锁了并且开启了
            if self._data.fun then
                self._data.fun()
            end
        else
            GameUtils.Toast(self.unOpenedToast)
        end
    else
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(self._data.systemToggleId))
    end
end

function UIOutDoorMainBtnNode:OnDestroy()
    if not isNull(self) then
        if self._co then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
    end

    self:RemoveRedPoint()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIOutDoorMainBtnNode
